CREATE TABLE IF NOT EXISTS connection_secrets(connection_id TEXT NOT NULL REFERENCES connections(id) ON DELETE CASCADE, org_id TEXT NOT NULL REFERENCES organizations(id), field TEXT NOT NULL CHECK(length(field) BETWEEN 1 AND 64), ciphertext TEXT NOT NULL CHECK(length(ciphertext) BETWEEN 1 AND 8192), nonce TEXT NOT NULL CHECK(length(nonce) BETWEEN 1 AND 128), wrapped_dek TEXT NOT NULL CHECK(length(wrapped_dek) BETWEEN 1 AND 2048), key_version INTEGER NOT NULL CHECK(key_version >= 1), algorithm TEXT NOT NULL CHECK(algorithm IN ('AES-GCM-256')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(connection_id, field));
CREATE INDEX IF NOT EXISTS connection_secrets_org ON connection_secrets(org_id);
